{
  "name": "cli-five",
  "version": "0.2.33",
  "description": "Code Like I'm Five — scaffold a 5-agent AI team (GitHub Copilot or OpenCode) into any repo.",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/idusortus/cli-five.git"
  },
  "homepage": "https://github.com/idusortus/cli-five#readme",
  "bugs": {
    "url": "https://github.com/idusortus/cli-five/issues"
  },
  "bin": {
    "cli-five": "bin/cli-five.mjs"
  },
  "files": [
    "bin",
    "src",
    "skills",
    "docs/BOOTSTRAP_AGENTIC_STACK_PROMPT.md",
    "docs/INSTALL_PROMPT.md",
    "templates",
    "plugin-agents",
    "plugin.json",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.mjs",
    "lint": "eslint .",
    "smoke": "node bin/cli-five.mjs --help"
  },
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "copilot",
    "opencode",
    "codegraph",
    "vscode",
    "agents",
    "scaffold",
    "ai"
  ],
  "license": "MIT",
  "dependencies": {
    "kleur": "^4.1.5",
    "prompts": "^2.4.2",
    "skills": "^1.5.0",
    "yaml": "^2.8.3"
  },
  "devDependencies": {
    "eslint": "^10.11.0",
    "globals": "^17.12.0"
  }
}

{
  "name": "cli-five-jev-tier-router",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "exports": {
    ".": "./index.js"
  }
}
